// ============ EDITOR VISUAL POSISI ELEMEN KARTU (drag & drop di atas template) ============

const TEMPLATE_EDITOR_DEFS = [
  { key: "logo",     type: "box",  label: "Logo" },
  { key: "foto",     type: "box",  label: "Foto" },
  { key: "qr",       type: "box",  label: "Barcode", lockAspect: true },
  { key: "judul",    type: "text", label: "Judul" },
  { key: "subjudul", type: "text", label: "Sub-judul" },
  { key: "nama",     type: "text", label: "Nama" },
  { key: "sekolah",  type: "text", label: "Sekolah" },
];

function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }

async function setupTemplateEditor() {
  const wrap = $("templateEditor");
  const src = cardSettings.template || DEFAULT_TEMPLATE_DATA_URL;
  wrap.innerHTML = "Memuat template...";
  try {
    const img = await loadImage(src);
    wrap.innerHTML = "";
    wrap.style.backgroundImage = `url(${src})`;
    wrap.style.aspectRatio = `${img.naturalWidth} / ${img.naturalHeight}`;
    TEMPLATE_EDITOR_DEFS.forEach(def => buildTemplateEditorElement(wrap, def));
  } catch (err) {
    wrap.innerHTML = `<p class="error">Gagal memuat template: ${esc(err.message)}</p>`;
  }
}

function buildTemplateEditorElement(wrap, def) {
  const elem = cardSettings.elements[def.key];
  const div = document.createElement("div");
  div.className = "tpl-el " + (def.type === "box" ? "tpl-box" : "tpl-text");
  div.dataset.key = def.key;
  div.innerHTML = `<span class="tpl-label">${esc(def.label)}</span>` +
    (def.type === "box" ? `<div class="tpl-resize"></div>` : "");
  wrap.appendChild(div);
  positionTemplateEditorElement(div, def, elem);
  attachTemplateDrag(div, wrap, def, elem);
}

function positionTemplateEditorElement(div, def, elem) {
  if (def.type === "box") {
    div.style.left = (elem.x0 * 100) + "%";
    div.style.top = (elem.y0 * 100) + "%";
    div.style.width = (elem.w * 100) + "%";
    div.style.height = (elem.h * 100) + "%";
  } else {
    div.style.left = (elem.x * 100) + "%";
    div.style.top = (elem.y * 100) + "%";
  }
}

function attachTemplateDrag(div, wrap, def, elem) {
  let dragging = false, startX = 0, startY = 0, orig = null;

  div.addEventListener("pointerdown", (e) => {
    if (e.target.classList.contains("tpl-resize")) return;
    dragging = true;
    div.setPointerCapture(e.pointerId);
    startX = e.clientX; startY = e.clientY;
    orig = { ...elem };
    e.preventDefault();
  });
  div.addEventListener("pointermove", (e) => {
    if (!dragging) return;
    const rect = wrap.getBoundingClientRect();
    const dx = (e.clientX - startX) / rect.width;
    const dy = (e.clientY - startY) / rect.height;
    if (def.type === "box") {
      elem.x0 = clamp(orig.x0 + dx, 0, 1 - elem.w);
      elem.y0 = clamp(orig.y0 + dy, 0, 1 - elem.h);
    } else {
      elem.x = clamp(orig.x + dx, 0.05, 0.95);
      elem.y = clamp(orig.y + dy, 0.03, 0.97);
    }
    positionTemplateEditorElement(div, def, elem);
  });
  div.addEventListener("pointerup", () => { dragging = false; });
  div.addEventListener("pointercancel", () => { dragging = false; });

  if (def.type === "box") {
    const handle = div.querySelector(".tpl-resize");
    let resizing = false, rStartX = 0, rStartY = 0, rOrig = null;
    handle.addEventListener("pointerdown", (e) => {
      resizing = true;
      handle.setPointerCapture(e.pointerId);
      rStartX = e.clientX; rStartY = e.clientY;
      rOrig = { ...elem };
      e.stopPropagation();
      e.preventDefault();
    });
    handle.addEventListener("pointermove", (e) => {
      if (!resizing) return;
      const rect = wrap.getBoundingClientRect();
      const dx = (e.clientX - rStartX) / rect.width;
      const dy = (e.clientY - rStartY) / rect.height;
      elem.w = clamp(rOrig.w + dx, 0.08, 1 - elem.x0);
      // Barcode dikunci rasio persegi (dalam piksel asli) supaya QR tidak
      // gepeng dan tetap mudah dipindai walau kartu di-print.
      elem.h = def.lockAspect
        ? clamp(elem.w * (rect.width / rect.height), 0.05, 1 - elem.y0)
        : clamp(rOrig.h + dy, 0.06, 1 - elem.y0);
      positionTemplateEditorElement(div, def, elem);
      e.stopPropagation();
    });
    handle.addEventListener("pointerup", (e) => { resizing = false; e.stopPropagation(); });
    handle.addEventListener("pointercancel", (e) => { resizing = false; e.stopPropagation(); });
  }
}

